-- S1 · parte 2.03: proyectos expandete-spot-juno-media, sin-tiempo-peiko, el-viajero
create function pg_temp.med(u text) returns uuid language sql as $$ select id from public.medios where url_origen = u order by creado_en limit 1 $$;
create function pg_temp.gal(urls text[]) returns jsonb language sql as $$ select coalesce(jsonb_agg(jsonb_build_object('medio', pg_temp.med(u), 'pie', '') order by o), '[]'::jsonb) from unnest(urls) with ordinality t(u, o) $$;

insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('spot-juno-media', 'expandete-spot-juno-media', 'EXPÁNDE(TE)', (select id from public.tipos_proyecto where slug = 'publicidad'), null, 'Josep Mira Lozano',
  'JUNO Media', 'Guion, dirección y montaje', 'Blackmagic Pocket 6K Pro', $t$[]$t$::jsonb,
  $t$Un spot que no parece un anuncio hasta el último plano.$t$, $t$JUNO Media quería contar su lema, «cine para sanar». Escribí una fábula: una niña con ideas infinitas ayuda a su vecino, bloqueado, a liberar las suyas. También hice el casting y busqué las localizaciones; la fotografía fue de Juanfran Jiménez. Es una pieza de muestra que no llegó a comercializarse.$t$, $t$- **Giro final.** Tres actos, y la marca solo aparece al final, con sus fundadoras haciendo de sí mismas.
- **Dos casas enfrentadas.** La niña y el adulto se miran a través de la ventana: esa mirada sostiene la historia.
- **Casting con oficio.** Amaia Miranda, actriz infantil con experiencia, para rodar rápido y natural.$t$, $t$Encontrar dos viviendas enfrentadas con las ventanas a la vista. Sin esa geografía, la historia no existía.$t$, '', $t$Un anuncio que se gana la atención *antes de pedirla*.$t$,
  'Pa6URCIllhE', null, $t$[]$t$::jsonb, false, pg_temp.med('https://i.imgur.com/Km09TG5.png'), pg_temp.gal(array['https://i.imgur.com/Km09TG5.png','https://i.ibb.co/Kj0zPfnz/Captura-de-pantalla-2026-05-12-183748.png','https://i.ibb.co/BKjhBXkX/Captura-de-pantalla-2026-05-12-183832.png','https://i.ibb.co/cjmJvQW/Captura-de-pantalla-2026-05-12-183854.png','https://i.ibb.co/HLMYh8Qq/Captura-de-pantalla-2026-05-12-183915.png','https://i.ibb.co/3yfgBhP9/Captura-de-pantalla-2026-05-12-183945.png','https://i.ibb.co/4wMbsJyt/Captura-de-pantalla-2026-05-12-184024.png']), null, 7, 'publicado', now())
