insert into public.proyecto_servicios (proyecto_id, servicio_id, orden, destacado) select p.id, s.id, 1, true from public.proyectos p, public.servicios s where p.id_antiguo = 'spot-juno-media' and s.slug = 'filmmaker' on conflict (proyecto_id, servicio_id) do update set orden = excluded.orden, destacado = excluded.destacado;
insert into public.proyecto_servicios (proyecto_id, servicio_id, orden, destacado) select p.id, s.id, 7, false from public.proyectos p, public.servicios s where p.id_antiguo = 'spot-juno-media' and s.slug = 'edicion' on conflict (proyecto_id, servicio_id) do update set orden = excluded.orden, destacado = excluded.destacado;

insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('sin-tiempo-peiko', 'sin-tiempo-peiko', 'Sin Tiempo, Peiko', (select id from public.tipos_proyecto where slug = 'videoclip'), null, 'Josep Mira Lozano',
  'Proyecto de estudios', 'Dirección y fotografía', 'Canon C200 · 50 mm', $t$[]$t$::jsonb,
  $t$Una canción sobre el paso del tiempo y la distancia entre el éxito y el fracaso, contada como un drama.$t$, $t$Peiko canta y, a la vez, vive la caída de su personaje. Pasé la canción a un plan de rodaje: cada movimiento de cámara y cada óptica acompañan ese arco.$t$, $t$- **Dos casas opuestas.** Una moderna y lujosa, otra podrida: dos atmósferas para la fractura del personaje.
- **Final en una celda.** La luz se enfría y Peiko termina cantando agarrado a los barrotes.$t$, $t$Que la caída se viera en la imagen y no solo en la letra.$t$, '', $t$Del lujo a *los barrotes*, al ritmo de una canción.$t$,
  'wCnVb2o-k7Y', null, $t$[]$t$::jsonb, false, pg_temp.med('https://i.imgur.com/uUiXiQT.png'), pg_temp.gal(array['https://i.imgur.com/uUiXiQT.png','https://i.ibb.co/MDqyCBQ1/Captura-de-pantalla-2026-05-12-193744.png','https://i.ibb.co/Df7JzTry/Captura-de-pantalla-2026-05-12-193832.png','https://i.ibb.co/q30FzfyN/Captura-de-pantalla-2026-05-12-193908.png','https://i.ibb.co/7JDnD0s9/Captura-de-pantalla-2026-05-12-194115.png']), null, 8, 'publicado', now())
