insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('el-viajero', 'el-viajero', 'El Viajero', (select id from public.tipos_proyecto where slug = 'cortometraje'), null, 'Josep Mira Lozano',
  'Proyecto de fin de ciclo, IES Veles e Vents', 'Guion, dirección y fotografía', 'Canon C200 · 50 mm', $t$[]$t$::jsonb,
  $t$Un relojero de los años 50 construye una máquina del tiempo, y su yo del futuro vuelve para advertirle.$t$, $t$Lo escribí y lo rodamos casi sin presupuesto, con un equipo mínimo: Alba Gisbert, Sebastian Alonso Pérez, Mar Garrido, Lara Ruiz Martín y Andreu Pastor. Música original de David Bellido y Jesús Jiménez.$t$, $t$- **Los 50 sin presupuesto.** Un apartamento antiguo y atrezo de casas de familiares.
- **Máquina hecha a mano.** Manivela, engranajes y tuberías que funcionan de verdad.
- **La bombilla como luz principal.** Clave baja, con la luz de la propia máquina.
- **Un clic de reloj.** La música, inspirada en Göransson, repite ese motivo todo el corto.$t$, $t$Hacer creíble una ciencia ficción de época sin dinero ni efectos. Todo tenía que existir delante de la cámara.$t$, $t$- Más de 22.000 visualizaciones en YouTube.$t$, $t$Sin dinero para efectos, construimos una máquina del tiempo *de verdad*.$t$,
  '-TZXzZCVf8Y', null, $t$[]$t$::jsonb, false, pg_temp.med('https://i.ytimg.com/vi/-TZXzZCVf8Y/maxresdefault.jpg'), pg_temp.gal(array['https://i.ytimg.com/vi/-TZXzZCVf8Y/maxresdefault.jpg','https://i.imgur.com/YFpoep5.png','https://i.imgur.com/COiqMyC.png','https://i.imgur.com/JFVS8SY.png','https://i.imgur.com/HjsEDrF.png','https://i.imgur.com/VOWw0tD.png','https://i.imgur.com/l0KwxAB.png']), null, 9, 'publicado', now())
